from pyats import aetest
from pyats.topology import loader


class CommonSetup(aetest.CommonSetup):
    @aetest.subsection
    def connect(self, testbed):
        testbed.connect(log_stdout=False)      # SSH to every device


class InterfacesUp(aetest.Testcase):
    @aetest.test
    def all_configured_interfaces_up(self, testbed):
        down = []
        for device in testbed.devices.values():
            parsed = device.parse("show ip interface brief")   # Genie parser
            for name, intf in parsed["interface"].items():
                if intf["ip_address"] != "unassigned" and intf["protocol"] != "up":
                    down.append(f"{device.name} {name}")
        if down:
            self.failed(f"Interfaces down: {down}")
        else:
            self.passed("All addressed interfaces are up/up")


class CommonCleanup(aetest.CommonCleanup):
    @aetest.subsection
    def disconnect(self, testbed):
        testbed.disconnect()


if __name__ == "__main__":
    aetest.main(testbed=loader.load("testbed.yaml"))

